   181          ef_structure = card->ef_dir->ef_structure;
   182          if (ef_structure == SC_FILE_EF_TRANSPARENT) {
   183                  u8 *buf = NULL, *p;
   184                  size_t bufsize;
   185
   186                  file_size = card->ef_dir->size;
   187                  if (file_size == 0)
   188                          LOG_FUNC_RETURN(ctx, 0);
   189                  if (file_size > MAX_FILE_SIZE)
   190                          LOG_FUNC_RETURN(ctx, SC_ERROR_INVALID_DATA);
   191
   192                  buf = malloc(file_size);
   193                  if (buf == NULL)
   194                          LOG_FUNC_RETURN(ctx, SC_ERROR_OUT_OF_MEMORY);
   195                  p = buf;
   196                  r = sc_read_binary(card, 0, buf, file_size, 0);
   197                  if (r < 0) {
   198                          free(buf);
   199                          LOG_TEST_RET(ctx, r, "sc_read_binary() failed");
   200                  }
   201                  bufsize = r;
   202                  while (bufsize > 0) {
   203                          if (card->app_count == SC_MAX_CARD_APPS) {
   204                                  sc_log(ctx, "Too many applications on card");
   205                                  break;
   206                          }
   207                          r = parse_dir_record(card, &p, &bufsize, -1);
   208                          if (r)
   209                                  break;
   210                  }
