   220                  /* Arbitrary set '16' as maximal number of records to check out:
   221                   * to avoid endless loop because of some incomplete cards/drivers */
   222                  for (rec_nr = 1; rec_nr < 16; rec_nr++) {
   223                          r = sc_read_record(card, rec_nr, buf, sizeof(buf), SC_RECORD_BY_REC_NR);
