   228                          if (card->app_count == SC_MAX_CARD_APPS) {
   229                                  sc_log(ctx, "Too many applications on card");
   230                                  break;
   231                          }
   232
   233                          rec_size = r;
   234                          p = buf;
   235                          parse_dir_record(card, &p, &rec_size, (int)rec_nr);
   236                  }
   237          }
   238
   239          /* Move known PKCS#15 applications to the head of the list */
   240          for (ii=0, idx=0; ii<card->app_count; ii++)   {
   241                  for (jj=0; jj < sizeof(apps)/sizeof(apps[0]); jj++) {
   242                          if (apps[jj].aid_len != card->app[ii]->aid.len)
   243                                  continue;
   244                          if (memcmp(apps[jj].aid, card->app[ii]->aid.value, apps[jj].aid_len))
