  2265  sc_pkcs15_parse_unusedspace(const unsigned char *buf, size_t buflen, struct sc_pkcs15_card *p15card)
  2266  {
  2267          const unsigned char *p = buf;
  2268          size_t left = buflen;
  2269          int r;
  2270          struct sc_path path;
  2271          struct sc_pkcs15_id auth_id;
  2272          struct sc_asn1_entry asn1_unusedspace[] = {
  2273                  { "UnusedSpace", SC_ASN1_STRUCT, SC_ASN1_TAG_SEQUENCE | SC_ASN1_CONS, 0, NULL, NULL },
  2274                  { NULL, 0, 0, 0, NULL, NULL }
  2275          };
  2276          struct sc_asn1_entry asn1_unusedspace_values[] = {
  2277                  { "path", SC_ASN1_PATH, SC_ASN1_TAG_SEQUENCE | SC_ASN1_CONS, 0, NULL, NULL },
  2278                  { "authId", SC_ASN1_PKCS15_ID, SC_ASN1_TAG_OCTET_STRING, SC_ASN1_OPTIONAL, NULL, NULL },
  2279                  { NULL, 0, 0, 0, NULL, NULL }
  2280          };
  2281
  2282          /* Clean the list if already present */
  2283          sc_pkcs15_free_unusedspace(p15card);
  2284
  2285          sc_format_asn1_entry(asn1_unusedspace, asn1_unusedspace_values, NULL, 1);
  2286          sc_format_asn1_entry(asn1_unusedspace_values, &path, NULL, 1);
  2287          sc_format_asn1_entry(asn1_unusedspace_values+1, &auth_id, NULL, 0);
  2288
  2289          while (left > 0) {
  2290                  memset(&auth_id, 0, sizeof(auth_id));
  2291                  r = sc_asn1_decode(p15card->card->ctx, asn1_unusedspace, p, left, &p, &left);
  2292                  if (r == SC_ERROR_ASN1_END_OF_CONTENTS)
  2293                          break;
  2294                  if (r < 0)
  2295                          return r;
  2296                  /* If the path length is 0, it's a dummy path then don't add it.
  2297                   * If the path length isn't included (-1) then it's against the standard
  2298                   *   but we'll just ignore it instead of returning an error. */
  2299                  if (path.count > 0 && p15card->file_app) {
  2300                          r = sc_pkcs15_make_absolute_path(&p15card->file_app->path, &path);
  2301                          if (r < 0)
  2302                                  return r;
  2303                          r = sc_pkcs15_add_unusedspace(p15card, &path, &auth_id);
  2304                          if (r)
  2305                                  return r;
  2306                  }
  2307          }
  2308
  2309          p15card->unusedspace_read = 1;
  2310
  2311          return 0;
  2312  }
